//
//! The build half of Zstandard's runtime-loading route: three modules and one
//! generated file.
//!
//! An SDK that ships the runtime route calls `createModule` in place of
//! `translate.createModule()` and imports what comes back as its `c` module.
//! Nothing here links the native library. That is the point: in this
//! configuration the symbols arrive through the platform loader at run time,
//! and linking the archive as well would make the linker demand them before
//! `load` ever runs.
//!
//!   rt        runtime/loader.zig, the reusable core. Pure Zig; imported by the
//!             facade in both configurations, because `LoadSource` and
//!             `LoadError` are this SDK's public types and must be the same
//!             types whichever configuration is built.
//!   library   runtime/library.zig, this SDK's descriptor: the namespaced
//!             synchronization binding and the load-time checks.
//!   dispatch  generated by runtime/generate.zig from the real translation
//!             output: the table, the wrappers, `load`, and the re-exported
//!             translated namespace. It imports `rt`, `library` and the
//!             generator's patched translation as `c_native`, which imports the
//!             dispatch back as `c_routed`.
//!   sync.c    compiled into the dispatch with `-DRT_SYNC_PREFIX=zstd_rt`, so
//!             its symbols cannot collide with another SDK's.
//!
//! ## The one thing a caller must not do
//!
//! Do not link the compiled C archive into a module that imports this dispatch.
//! The facade's `c` import is the dispatch, and nothing else in the graph should
//! reference the library, or the linker resolves the symbols statically and the
//! runtime route silently becomes a linked one.
//!
//! ## What is routed, and what is not
//!
//! The translated header for this SDK is `zig/translate.h`, which includes
//! exactly `<zstd.h>`, `<zdict.h>` and `<zstd_errors.h>` and defines no macro
//! other than its own include guard. Those three headers declare 189 distinct
//! `ZSTD_`/`ZDICT_` functions - a text scan of the three files for the names
//! that follow `ZSTDLIB_API`, `ZSTDLIB_STATIC_API`, `ZDICTLIB_API`,
//! `ZDICTLIB_STATIC_API` and `ZSTDERRORLIB_API` finds that many - and not one
//! data object: none of the three contains a bare `extern` declaration, so
//! there is no exported variable for a provider to owe. Every one of those 189
//! names is routed, which means a provider that does not export the whole
//! header-declared API is refused rather than half used. `provider_optional`
//! and `provider_excluded` below are therefore empty, and are written out
//! rather than omitted so that adding a header with an optional or
//! deliberately-direct entry point is a change in this file with a name in it.
//!
//! Zstandard's public headers reach the C library through exactly two standard
//! headers, and that is what decides the `libc_noise` question below.
//! `src/lib/zstd.h:16` opens `<stddef.h>` for `size_t`, `src/lib/zstd.h:18`
//! opens upstream's own `"zstd_errors.h"`, and `src/lib/zstd.h:20` opens
//! `<limits.h>` for `INT_MAX`; `src/lib/zdict.h:16` opens `<stddef.h>` a second
//! time; and `src/lib/zstd_errors.h` includes nothing at all. Those are the
//! only `#include` directives in the three headers, so the whole include
//! closure `zig translate-c` walks is `<stddef.h>` and `<limits.h>`.
//!
//! ## The `libc_noise` list, and how it was derived
//!
//! The method was text analysis of system headers, not a translation, because
//! no translation was observed: `zig translate-c` was not run over this
//! package's `zig/translate.h`, and the result below is therefore a reasoned
//! superset rather than an observed one.
//!
//! The scan resolved `<stddef.h>` and `<limits.h>` against the include roots
//! of the host C library (`/usr/include`,
//! `/usr/include/x86_64-linux-gnu`, and the GCC private include directory),
//! followed every `#include` in the closure textually, stripped comments, and
//! collected every `identifier (` at brace depth zero. Nineteen headers are
//! reached and **not one of them declares a function**: every candidate the
//! scan produced is a preprocessor macro - `INT_MIN`, `LLONG_MIN`,
//! `__LDBL_REDIR_NTH`, `__GLIBC_PREREQ`, `__attribute_*__`, `_Static_assert`
//! and their neighbours - and a macro cannot survive into a translation as a
//! declaration. The three unresolved include names the scan reported are
//! `gnu/stubs-32.h`, `gnu/stubs-x32.h` (the 32- and x32-ABI stub headers,
//! which do not exist on a 64-bit host) and `stddef.h` itself, which the GCC
//! private directory resolves and which declares `size_t`, `ptrdiff_t`,
//! `nullptr_t`, `max_align_t` and `offsetof` and nothing that is callable.
//!
//! So the list is empty, and that is a result rather than an omission.
//!
//! Over-listing is safe and under-listing is not. A name in `libc_noise` that
//! a given target's translation does not contain matches no declaration and
//! costs nothing; a name that a target's translation *does* contain and that is
//! absent from this list is routed as if it were Zstandard's own, and every
//! load then fails with `MissingSymbol` on a symbol the provider never owed.
//! The list is therefore kept empty only while the scan says the closure
//! declares nothing, and the next edit to `zig/translate.h` that adds an
//! `#include` of anything with function declarations has to re-run the scan
//! and re-enter the names here.
//!
//! The first gate that would observe a shortfall is
//! `zig build test -Druntime=true` with `ZSTD_TEST_PROVIDER` naming a shared
//! object that exports Zstandard's API: the generated dispatch resolves every
//! routed name through the platform loader, so an under-listed C-library name
//! surfaces there as `error.MissingSymbol` and nothing earlier. This is an
//! open risk, recorded as one in [`FORK-NOTES.md`](FORK-NOTES.md).
//!
//! Two other facts hold the answer in place. The `ZSTD_STATIC_LINKING_ONLY`
//! macro `build.zig` puts on the translation line - without it
//! `ZSTD_frameHeaderSize` and `ZSTD_CCtx_getParameter` are not declared at
//! all, and the facade could not wrap them - changes which of Zstandard's own
//! declarations are visible and reaches no other header. And the same macro on
//! the library's own C lines selects branches inside upstream's `.c` units,
//! never an include, so the closure above is the same one with and without it.

const std = @import("std");

/// The prefix `runtime/sync.c` is compiled with.
///
/// `runtime/library.zig` declares the same prefix in the symbol names it binds.
/// The two must agree, and a build where they do not fails to link, which is
/// the whole error report: there is no runtime path that could hide it.
///
/// A build that needs a second, independent instance of this SDK in one binary
/// should change this value *and* the prefix in `runtime/library.zig`, and then
/// give the second instance its own copy of both files. Nothing else in the
/// package assumes one instance.
const sync_prefix = "zstd_rt";

/// `extern` declarations that are the C library's, not Zstandard's.
///
/// **Empty, and that is a measured result rather than an omission.** See
/// "The `libc_noise` list, and how it was derived" in this file's module
/// comment for the scan, the headers it followed, the nineteen files it
/// reached and why none of them declares a function. In one line: the three
/// translated headers include `<stddef.h>` and `<limits.h>` and nothing else
/// (`src/lib/zstd.h:16,18,20` and `src/lib/zdict.h:16`), and neither of those
/// two declares a callable in any libc family this package can be built for.
///
/// ### Why it is written out rather than omitted
///
/// `runtime/generate.zig` reads this list through
/// `std.mem.splitScalar(u8, list, ',')` followed by a whitespace trim. An
/// empty string splits into one empty field, which trims to one empty name,
/// and that name matches no declaration - so the empty literal is inert and
/// costs nothing. Spelling it out means the next reader sees the decision
/// where the list would have been instead of having to infer it from its
/// absence.
///
/// ### Why a future edit here must re-run the scan
///
/// Over-listing is safe: a name that a target's translation does not contain
/// matches nothing. Under-listing is not: a C-library declaration that reaches
/// the translation and is absent from this list is routed as if it were
/// Zstandard's own, `libzstd.so` does not export it, and every load fails with
/// `MissingSymbol` on a symbol no provider ever owed. The gate that would see
/// it is `zig build test -Druntime=true` with `ZSTD_TEST_PROVIDER` named.
const libc_noise = "";

/// `extern` declarations the provider may legitimately not have.
///
/// Two, and both are the same finding: `src/lib/zstd.h:1907-1908` declares
/// `ZSTD_createThreadPool` and `ZSTD_freeThreadPool` unconditionally, with no
/// macro around either, but `src/lib/common/pool.c` defines them only inside
/// the `#ifdef ZSTD_MULTITHREAD` that `:24` opens and `:313` closes. This build
/// does not define that macro - `src/lib/Makefile:64` leaves
/// `CPPFLAGS_STATICLIB` empty - so the library this tree compiles does not
/// export them, and a provider built from it is a conforming provider that
/// fails `MissingSymbol` on two names it was never going to have.
///
/// That is what the optional list is for: the load succeeds, the table field
/// stays null, and a call stops the program by name rather than becoming a
/// link-time reference to a symbol nothing links. `ZSTD_CCtx_refThreadPool`
/// (`:1910`) is declared beside them and is *not* here, because
/// `src/lib/compress/zstd_compress.c:1338` defines it unconditionally.
const provider_optional = "ZSTD_createThreadPool,ZSTD_freeThreadPool";

/// `extern` declarations this build does not require a provider to export.
///
/// None. Every header-declared Zstandard entry point is either required or, for
/// the two the optional list names, optional; there is no third category here
/// and no name deliberately kept out of the table.
///
/// A name here is routed and optional rather than direct; only
/// `libc_noise` above stays direct.
const provider_excluded = "";

/// The loader core, for a *linked* build to import.
///
/// A linked build has no dispatch, so the facade needs the core module itself
/// for the two public types `LoadSource` and `LoadError`: they are this SDK's
/// types and they must be the same types a caller names in either
/// configuration. It costs a linked build two declarations and no code, since
/// nothing else in that module is referenced until a configuration actually
/// instantiates the loader.
///
/// A runtime-loading build must *not* import this separately: `createModule`
/// makes the one core instance the dispatch uses, and the dispatch re-exports
/// the two types from it. Two instances would be two sets of types, and a
/// consumer would be naming one while `load` expects the other.
pub fn createCoreModule(
    b: *std.Build,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
) *std.Build.Module {
    return b.createModule(.{
        .root_source_file = b.path("runtime/loader.zig"),
        .target = target,
        .optimize = optimize,
        // The Unix backend calls `dlopen`, which is libc. Nothing in this module
        // is compiled into a linked build, so this costs nothing there.
        .link_libc = true,
    });
}

/// The runtime-loaded `c` module for one target.
///
/// `translate` is the translation step for that same target and configuration;
/// its output is read by the generator, so the dispatch describes the headers
/// this build actually selected rather than another one.
pub fn createModule(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
) *std.Build.Module {
    const core = createCoreModule(b, target, optimize);

    const library = b.createModule(.{
        .root_source_file = b.path("runtime/library.zig"),
        .target = target,
        .optimize = optimize,
    });
    library.addImport("rt", core);
    // The same translation the generator below reads, so `validate`'s call
    // arguments come from the headers this build selected rather than from
    // numbers written here. `ZSTD_CLEVEL_DEFAULT` is the one it needs
    // (`src/lib/zstd.h:133-136`). It cannot reach the dispatch's own
    // `c_native`: the dispatch imports `library`, so that would be a cycle, and
    // `c_native` in turn imports the dispatch.
    library.addImport("c", translate.createModule());

    return createDispatchModule(b, translate, target, optimize, core, library);
}

const GeneratedSources = struct {
    native: std.Build.LazyPath,
    dispatch: std.Build.LazyPath,
};

fn createDispatchModule(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
    core: *std.Build.Module,
    library: *std.Build.Module,
) *std.Build.Module {
    const sources = generateDispatch(b, translate, target);

    const dispatch = b.createModule(.{
        .root_source_file = sources.dispatch,
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    dispatch.addImport("rt", core);
    dispatch.addImport("library", library);
    // The translated headers, under a name that says what it is. Every type and
    // constant in the dispatch is re-exported from here rather than restated, so
    // `c.ZSTD_CCtx` in a facade and `c_native.ZSTD_CCtx` in the dispatch are one
    // type.
    //
    // The root is the generator's *patched* translation, not the raw one the
    // translate step wrote. `const __root = @import("c_routed");` is what makes
    // a macro-expanded struct member that names a library function resolve to
    // the routed wrapper rather than escaping to a native `extern` this route
    // never links. That repointing is why the two modules import each other.
    const native = b.createModule(.{
        .root_source_file = sources.native,
        .target = target,
        .optimize = optimize,
        .link_libc = true,
    });
    native.addImport("c_routed", dispatch);
    dispatch.addImport("c_native", native);
    dispatch.addCSourceFiles(.{
        .files = &.{"runtime/sync.c"},
        .flags = &.{b.fmt("-DRT_SYNC_PREFIX={s}", .{sync_prefix})},
        .language = .c,
    });
    return dispatch;
}

/// Runs the generator over the translation step's real output.
///
/// The generator is a host program built and run by this build, so the dispatch
/// is produced for the target being built from that target's own translation.
/// Nothing is cached across configurations: a different header configuration
/// produces a different translation step output, which produces a different
/// dispatch.
fn generateDispatch(
    b: *std.Build,
    translate: *std.Build.Step.TranslateC,
    target: std.Build.ResolvedTarget,
) GeneratedSources {
    const generator = b.addExecutable(.{
        .name = b.fmt("zstd-runtime-generate-{s}", .{
            target.result.zigTriple(b.allocator) catch @panic("unspellable target"),
        }),
        .root_module = b.createModule(.{
            .root_source_file = b.path("runtime/generate.zig"),
            .target = b.graph.host,
            .optimize = .Debug,
        }),
    });

    const run = b.addRunArtifact(generator);
    run.addArg("--library");
    run.addArg("zstd");
    run.addArg("--translate");
    run.addFileArg(translate.getOutput());
    if (libc_noise.len != 0) {
        run.addArg("--noise");
        run.addArg(libc_noise);
    }
    if (provider_optional.len != 0) {
        run.addArg("--optional");
        run.addArg(provider_optional);
    }
    if (provider_excluded.len != 0) {
        run.addArg("--exclude");
        run.addArg(provider_excluded);
    }
    run.addArg("--native-output");
    const native_source = run.addOutputFileArg("native.zig");
    run.addArg("--output");
    const dispatch_source = run.addOutputFileArg("dispatch.zig");
    return .{ .native = native_source, .dispatch = dispatch_source };
}